// Minimal Unicode classification for the Inkling 2 pre-tokenizer (no ICU).
// Tables are generated by tools/gen_unicode_tables.py.
#pragma once

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace inkling2::text::unicode {

struct CodepointRange {
  std::uint32_t first;
  std::uint32_t last;
  std::uint8_t code;  // low 7 bits: category (below); 0x80: White_Space
};

extern const CodepointRange kRanges[];
extern const std::size_t kRangeCount;

enum Category : std::uint8_t {
  kOther = 0,
  kLu = 1,
  kLt = 2,
  kLm = 3,
  kLo = 4,
  kLl = 5,
  kMark = 6,    // Mn | Mc | Me
  kNumber = 7,  // Nd | Nl | No
};

/// Category code (low 7 bits) | 0x80 when White_Space. 0 for everything else.
[[nodiscard]] std::uint8_t Lookup(char32_t cp) noexcept;

[[nodiscard]] inline Category CategoryOf(std::uint8_t code) noexcept {
  return static_cast<Category>(code & 0x7F);
}
[[nodiscard]] inline bool IsSpaceCode(std::uint8_t code) noexcept {
  return (code & 0x80) != 0;
}

/// One decoded code point. Invalid bytes decode as value 0x110000 + byte with
/// length 1 so that they never match a letter, number or white-space class.
struct Decoded {
  char32_t cp;
  std::uint8_t len;
};
[[nodiscard]] Decoded DecodeUtf8(std::string_view s, std::size_t pos) noexcept;

}  // namespace inkling2::text::unicode
